      // restaurant record before switching the native app; the compact card
      // details alone are insufficient for Five Guys' location bootstrap.
      const found = await request('/restaurants/' + encodeURIComponent(recipe.storeId), 'GET');
      const selected = found?.restaurant || found?.data?.restaurant || found?.data || found;
      if (String(selected?.id || '') !== recipe.storeId) {
        fail('Five Guys did not confirm the selected restaurant. Choose ' + recipe.store.name +
          ' on the official site, then retry OPEN CART.', 'FIVE_GUYS_STORE_MISMATCH');
      }
